import { GameConfig, ModelKey } from './types';

const MODEL_KEYS: readonly ModelKey[] = Object.freeze([
    'block_00', 'block_01', 'block_03', 'block_04', 'block_08',
    'block_11', 'block_12', 'block_33', 'block_34', 'block_35',
] as ModelKey[]);

/** Single authoritative set of learning-version runtime values. */
export const DEFAULT_GAME_CONFIG: Readonly<GameConfig> = Object.freeze({
    configVersion: 'jump-learning-1.0', seed: 20260930,
    fixedStepSeconds: 1 / 60, maxTicksPerFrame: 5,
    minChargeSeconds: 0.08, maxChargeSeconds: 1.20,
    minJumpDistance: 4, maxJumpDistance: 22,
    verticalVelocity: 24, gravity: 80,
    platformWidth: 10, platformDepth: 10, platformHeight: 5.5,
    minPlatformScale: 0.8, maxPlatformScale: 1,
    minEdgeGap: 2, maxEdgeGap: 8,
    safeRadius: 0.30, centerRadius: 0.50, geometryEpsilon: 1e-6,
    cameraMoveSeconds: 0.25, initialTargetDistance: 14,
    platformPoolLimit: 8, normalScore: 1, centerScoreMultiplier: 2,
    maxRewardStreak: 8, modelKeys: MODEL_KEYS,
});

export function normalizeSeed(seed: number): number {
    if (!Number.isInteger(seed) || seed < 0 || seed > 0xffffffff) {
        throw new RangeError('seed must be an unsigned 32-bit integer');
    }
    return seed === 0 ? 1 : seed;
}

/** Throws before any run starts. Does not perform stage02 ray reachability. */
export function validateGameConfig(config: GameConfig): void {
    if (typeof config.configVersion !== 'string' || !config.configVersion.trim()) {
        throw new Error('configVersion must be non-empty');
    }
    normalizeSeed(config.seed);
    const positive: (keyof GameConfig)[] = [
        'fixedStepSeconds', 'maxTicksPerFrame', 'minChargeSeconds', 'maxChargeSeconds',
        'minJumpDistance', 'maxJumpDistance', 'verticalVelocity', 'gravity',
        'platformWidth', 'platformDepth', 'platformHeight', 'minPlatformScale',
        'maxPlatformScale', 'centerRadius', 'geometryEpsilon', 'cameraMoveSeconds',
        'initialTargetDistance', 'platformPoolLimit', 'normalScore',
        'centerScoreMultiplier', 'maxRewardStreak',
    ];
    for (const key of positive) {
        const value = config[key];
        if (typeof value !== 'number' || !Number.isFinite(value) || value <= 0) {
            throw new RangeError(`${key} must be finite and positive`);
        }
    }
    for (const key of ['minEdgeGap', 'maxEdgeGap', 'safeRadius'] as const) {
        if (!Number.isFinite(config[key]) || config[key] < 0) throw new RangeError(`${key} must be non-negative`);
    }
    for (const key of ['maxTicksPerFrame', 'platformPoolLimit', 'normalScore', 'centerScoreMultiplier', 'maxRewardStreak'] as const) {
        if (!Number.isSafeInteger(config[key])) throw new RangeError(`${key} must be a safe integer`);
    }
    if (config.maxTicksPerFrame > 5) throw new RangeError('at most 5 ticks per render frame');
    if (config.platformPoolLimit < 4) throw new RangeError('pool must hold current, target, history and preview');
    if (config.maxChargeSeconds <= config.minChargeSeconds) throw new RangeError('charge interval must increase');
    if (config.maxJumpDistance < config.minJumpDistance) throw new RangeError('distance interval inverted');
    if (config.maxPlatformScale < config.minPlatformScale || config.maxEdgeGap < config.minEdgeGap) {
        throw new RangeError('platform interval inverted');
    }
    const safeHalf = Math.min(config.platformWidth, config.platformDepth) * config.minPlatformScale / 2 - config.safeRadius;
    if (safeHalf <= 0 || config.centerRadius > safeHalf) throw new RangeError('invalid safe/center radii');
    if (config.geometryEpsilon >= Math.min(safeHalf, config.minChargeSeconds)) throw new RangeError('epsilon too large');
    if (config.initialTargetDistance < config.minJumpDistance || config.initialTargetDistance > config.maxJumpDistance) {
        throw new RangeError('initial target outside jump range');
    }
    if (!Array.isArray(config.modelKeys) || config.modelKeys.length !== MODEL_KEYS.length ||
        config.modelKeys.some((key, index) => key !== MODEL_KEYS[index])) {
        throw new Error('model whitelist/order must match learning contract');
    }
}

export function createGameConfig(overrides: Partial<GameConfig> = {}): Readonly<GameConfig> {
    const merged = { ...DEFAULT_GAME_CONFIG, ...overrides };
    validateGameConfig(merged);
    return Object.freeze({ ...merged, seed: normalizeSeed(merged.seed), modelKeys: Object.freeze([...merged.modelKeys]) });
}

export interface XZ { readonly x: number; readonly z: number; }
export interface FootPosition extends XZ { readonly y: number; }
export type ModelKey = 'block_00' | 'block_01' | 'block_03' | 'block_04' | 'block_08' | 'block_11' | 'block_12' | 'block_33' | 'block_34' | 'block_35';

export interface GameConfig {
    readonly configVersion: string;
    readonly seed: number;
    readonly fixedStepSeconds: number;
    readonly maxTicksPerFrame: number;
    readonly minChargeSeconds: number;
    readonly maxChargeSeconds: number;
    readonly minJumpDistance: number;
    readonly maxJumpDistance: number;
    readonly verticalVelocity: number;
    readonly gravity: number;
    readonly platformWidth: number;
    readonly platformDepth: number;
    readonly platformHeight: number;
    readonly minPlatformScale: number;
    readonly maxPlatformScale: number;
    readonly minEdgeGap: number;
    readonly maxEdgeGap: number;
    readonly safeRadius: number;
    readonly centerRadius: number;
    readonly geometryEpsilon: number;
    readonly cameraMoveSeconds: number;
    readonly initialTargetDistance: number;
    readonly platformPoolLimit: number;
    readonly normalScore: number;
    readonly centerScoreMultiplier: number;
    readonly maxRewardStreak: number;
    readonly modelKeys: readonly ModelKey[];
}
interface PlatformBase {
    readonly id: number;
    readonly centerXZ: XZ;
    readonly topY: number;
    readonly modelKey: ModelKey;
    readonly horizontalScale: number;
}
export type PlatformSpec = PlatformBase & (
    { readonly shape: 'rect'; readonly halfExtent: XZ; } |
    { readonly shape: 'circle'; readonly radius: number; }
);
export type ActivePhase = 'ready' | 'charging' | 'airborne' | 'landing' | 'recentering' | 'falling';
export type Phase = 'menu' | ActivePhase | 'paused' | 'gameover';
export interface CallbackToken { readonly runId: number; readonly jumpId?: number; }
export interface JumpToken extends CallbackToken { readonly jumpId: number; }
export interface JumpPlan extends JumpToken {
    readonly startFoot: FootPosition;
    readonly directionXZ: XZ;
    readonly startTick: number;
    readonly distance: number;
    readonly flightTime: number;
    readonly targetId: number;
}
export type JumpPlanDraft = Omit<JumpPlan, 'runId' | 'jumpId' | 'startTick'>;
export type LandingOutcome = 'target' | 'current';
export interface RunState {
    readonly runId: number;
    readonly phase: Phase;
    readonly resumePhase: Exclude<ActivePhase, 'charging'> | null;
    readonly tick: number;
    readonly seed: number;
    readonly score: number;
    readonly streak: number;
    readonly currentId: number | null;
    readonly targetId: number | null;
    readonly jumpId: number | null;
    readonly chargeStartTick: number | null;
    readonly inputOwner: string | null;
    readonly jumpPlan: JumpPlan | null;
    readonly landingOutcome: LandingOutcome | null;
}
interface EventBase { readonly runId: number; readonly tick: number; }
export type DomainEvent = EventBase & (
    { readonly type: 'Started'; readonly seed: number; } |
    { readonly type: 'Charge'; readonly action: 'begin' | 'cancel'; readonly source: string; readonly reason?: string; } |
    { readonly type: 'Jump'; readonly jumpId: number; readonly plan: JumpPlan; } |
    { readonly type: 'Landed'; readonly jumpId: number; readonly outcome: LandingOutcome; } |
    { readonly type: 'Scored'; readonly jumpId: number; readonly delta: number; readonly score: number; readonly streak: number; } |
    { readonly type: 'Failed'; readonly jumpId: number; readonly reason: string; } |
    { readonly type: 'Paused'; readonly resumePhase: Exclude<ActivePhase, 'charging'>; readonly reason: string; } |
    { readonly type: 'Resumed'; readonly phase: Exclude<ActivePhase, 'charging'>; } |
    { readonly type: 'Returned'; }
);
export interface ReplayInput {
    readonly tick: number;
    readonly type: 'press' | 'release' | 'cancel' | 'pause' | 'resume';
    readonly source: string;
}
export interface ReplayResult {
    readonly tick: number;
    readonly jumpId: number;
    readonly classification: 'target-normal' | 'target-center' | 'current' | 'miss';
    readonly foot: FootPosition;
    readonly score: number;
    readonly streak: number;
}
export interface ReplayRecord {
    readonly configVersion: string;
    readonly seed: number;
    readonly inputs: readonly ReplayInput[];
    readonly results: readonly ReplayResult[];
}

import { createGameConfig, DEFAULT_GAME_CONFIG } from './config';
import { GameConfig } from './types';

export interface ClockFrame {
    readonly tick: number;
    readonly ticksThisFrame: number;
    readonly pendingSeconds: number;
    readonly frozen: boolean;
    readonly freezeReason: 'paused' | 'backlog' | null;
    readonly recovering: boolean;
    readonly interpolationAlpha: number;
}
export interface TickClock {
    readonly tick: number;
    advanceFrame(deltaSeconds: number, onTick: (tick: number) => void): ClockFrame;
    pause(): void;
    resume(): void;
    reset(): void;
}

/** Wall time is supplied by an adapter; this module never reads Date/performance. */
export class FixedTickClock implements TickClock {
    private readonly config: Readonly<GameConfig>;
    private currentTick = 0;
    private accumulator = 0;
    private reason: 'paused' | 'backlog' | null = null;
    private skipNextDelta = false;
    private recovery = false;
    constructor(config: GameConfig = DEFAULT_GAME_CONFIG) { this.config = createGameConfig(config); }
    get tick(): number { return this.currentTick; }
    get snapshot(): ClockFrame { return this.result(0); }
    pause(): void { if (this.reason === null) this.reason = 'paused'; }
    resume(): void {
        if (this.reason === null) return;
        this.recovery = this.recovery || this.pendingTicks() > this.config.maxTicksPerFrame;
        this.reason = null;
        this.skipNextDelta = true;
    }
    reset(): void {
        this.currentTick = 0; this.accumulator = 0; this.reason = null;
        this.skipNextDelta = false; this.recovery = false;
    }
    advanceFrame(deltaSeconds: number, onTick: (tick: number) => void): ClockFrame {
        if (!Number.isFinite(deltaSeconds) || deltaSeconds < 0) throw new RangeError('deltaSeconds must be finite and non-negative');
        if (this.reason !== null) return this.result(0);
        if (this.skipNextDelta) this.skipNextDelta = false;
        else if (!this.recovery) this.accumulator += deltaSeconds;
        if (!Number.isFinite(this.accumulator)) throw new RangeError('wall time overflow');
        let due = this.pendingTicks();
        if (!this.recovery && due > this.config.maxTicksPerFrame) {
            this.reason = 'backlog';
            return this.result(0); // No lost ticks and no extra charging ticks.
        }
        const limit = Math.min(due, this.config.maxTicksPerFrame);
        let count = 0;
        while (count < limit && this.reason === null) {
            if (!Number.isSafeInteger(this.currentTick + 1)) throw new RangeError('tick overflow');
            this.accumulator = Math.max(0, this.accumulator - this.config.fixedStepSeconds);
            this.currentTick++;
            count++;
            onTick(this.currentTick);
        }
        due = this.pendingTicks();
        if (this.recovery && due === 0) this.recovery = false;
        return this.result(count);
    }
    private pendingTicks(): number {
        // Only compensate rounding at integer boundaries; not the gameplay epsilon.
        return Math.floor(this.accumulator / this.config.fixedStepSeconds + 1e-9);
    }
    private result(count: number): ClockFrame {
        return Object.freeze({ tick: this.currentTick, ticksThisFrame: count,
            pendingSeconds: this.accumulator, frozen: this.reason !== null,
            freezeReason: this.reason, recovering: this.recovery,
            interpolationAlpha: Math.min(1, this.accumulator / this.config.fixedStepSeconds) });
    }
}

import { createGameConfig, DEFAULT_GAME_CONFIG, normalizeSeed } from './config';
import { ActivePhase, CallbackToken, DomainEvent, GameConfig, JumpPlan, JumpPlanDraft, JumpToken, LandingOutcome, RunState } from './types';

export type JumpEventKind = 'Scored' | 'Failed';
/** Publication boundary only; deliberately contains no collision or reward rules. */
export class JumpEventBoundary {
    private runId = 0;
    private lastJumpId = 0;
    private activeJumpId: number | null = null;
    private claimed = new Set<JumpEventKind>();
    startRun(runId: number): boolean {
        if (!Number.isSafeInteger(runId) || runId <= this.runId) return false;
        this.runId = runId; this.lastJumpId = 0; this.activeJumpId = null; this.claimed.clear();
        return true;
    }
    openJump(token: JumpToken): boolean {
        if (token.runId !== this.runId || !Number.isSafeInteger(token.jumpId) || token.jumpId <= this.lastJumpId) return false;
        this.lastJumpId = token.jumpId; this.activeJumpId = token.jumpId; this.claimed.clear();
        return true;
    }
    closeJump(token: JumpToken): boolean {
        if (token.runId !== this.runId || token.jumpId !== this.activeJumpId) return false;
        this.activeJumpId = null; this.claimed.clear(); return true;
    }
    claim(token: JumpToken, kind: JumpEventKind): boolean {
        if ((kind !== 'Scored' && kind !== 'Failed') || token.runId !== this.runId ||
            token.jumpId !== this.activeJumpId || this.claimed.has(kind)) return false;
        this.claimed.add(kind);
        return true;
    }
}

export type RunCommand =
    { readonly type: 'start'; readonly seed?: number; } |
    { readonly type: 'home'; readonly runId: number; } |
    { readonly type: 'charge'; readonly runId: number; readonly source: string; } |
    { readonly type: 'cancel'; readonly runId: number; readonly source?: string; readonly reason?: string; } |
    { readonly type: 'launch'; readonly runId: number; readonly source: string; readonly plan: JumpPlanDraft; } |
    { readonly type: 'pause'; readonly runId: number; readonly reason?: string; } |
    { readonly type: 'resume'; readonly runId: number; } |
    ({ readonly type: 'land'; readonly outcome: LandingOutcome; } & JumpToken) |
    ({ readonly type: 'beginRecenter'; } & JumpToken) |
    ({ readonly type: 'finishRecenter'; readonly currentId: number; readonly targetId: number; } & JumpToken) |
    ({ readonly type: 'finishLanding'; } & JumpToken) |
    ({ readonly type: 'fall'; readonly reason?: string; } & JumpToken) |
    ({ readonly type: 'finishFall'; } & JumpToken);
export interface CommandResult {
    readonly accepted: boolean;
    readonly reason: string | null;
    readonly state: Readonly<RunState>;
    readonly events: readonly DomainEvent[];
}

export class RunStateMachine {
    private readonly config: Readonly<GameConfig>;
    private value: Readonly<RunState>;
    private nextJumpId = 0;
    private fallReason = 'miss';
    private readonly boundary = new JumpEventBoundary();
    constructor(config: GameConfig = DEFAULT_GAME_CONFIG) {
        this.config = createGameConfig(config);
        this.value = this.emptyState(0, 'menu', this.config.seed);
    }
    get state(): Readonly<RunState> { return this.value; }
    isCurrent(token: CallbackToken): boolean {
        return token.runId === this.value.runId && this.value.phase !== 'menu' &&
            (token.jumpId === undefined || token.jumpId === this.value.jumpId);
    }
    guardCallback(token: CallbackToken, callback: () => void): boolean {
        if (!this.isCurrent(token) || this.value.phase === 'paused' || this.value.phase === 'gameover') return false;
        callback(); return true;
    }
    advanceTick(): boolean {
        if (['menu', 'paused', 'gameover'].includes(this.value.phase)) return false;
        if (!Number.isSafeInteger(this.value.tick + 1)) throw new RangeError('tick overflow');
        this.patch({ tick: this.value.tick + 1 }); return true;
    }
    /** Phase02 must atomically combine this reservation with its score reducer/event. */
    claimJumpEvent(token: JumpToken, kind: 'Scored'): boolean {
        if (!this.isCurrent(token) || this.value.phase !== 'landing' || this.value.landingOutcome !== 'target') return false;
        return this.boundary.claim(token, kind);
    }
    dispatch(command: RunCommand): CommandResult {
        const events: DomainEvent[] = [];
        const reject = (reason: string) => this.result(false, reason, events);
        const emit = (event: DomainEvent) => events.push(Object.freeze(event));
        const base = () => ({ runId: this.value.runId, tick: this.value.tick });
        if (command.type === 'start') {
            let seed: number;
            try { seed = normalizeSeed(command.seed === undefined ? this.config.seed : command.seed); }
            catch (_) { return reject('invalid-seed'); }
            const runId = this.value.runId + 1;
            if (!Number.isSafeInteger(runId)) return reject('run-id-overflow');
            this.value = this.emptyState(runId, 'ready', seed);
            this.nextJumpId = 0; this.fallReason = 'miss'; this.boundary.startRun(runId);
            emit({ ...base(), type: 'Started', seed });
            return this.result(true, null, events);
        }
        if (!this.isCurrent(command)) return reject('stale-token');
        if (['land', 'beginRecenter', 'finishRecenter', 'finishLanding', 'fall', 'finishFall'].includes(command.type)) {
            const jumpId = (command as JumpToken).jumpId;
            if (!Number.isSafeInteger(jumpId) || jumpId <= 0 || jumpId !== this.value.jumpId) return reject('stale-jump');
        }
        switch (command.type) {
            case 'home': {
                const runId = this.value.runId + 1;
                if (!Number.isSafeInteger(runId)) return reject('run-id-overflow');
                emit({ ...base(), type: 'Returned' });
                this.value = this.emptyState(runId, 'menu', this.value.seed);
                this.boundary.startRun(runId); this.nextJumpId = 0;
                break;
            }
            case 'charge':
                if (this.value.phase !== 'ready') return reject('illegal-phase');
                if (typeof command.source !== 'string' || !command.source.trim()) return reject('invalid-source');
                this.patch({ phase: 'charging', inputOwner: command.source, chargeStartTick: this.value.tick });
                emit({ ...base(), type: 'Charge', action: 'begin', source: command.source });
                break;
            case 'cancel':
                if (this.value.phase !== 'charging') return reject('illegal-phase');
                if (command.source !== undefined && command.source !== this.value.inputOwner) return reject('not-owner');
                this.cancelCharge(events, command.reason || 'cancel');
                break;
            case 'launch': {
                if (this.value.phase !== 'charging') return reject('illegal-phase');
                if (command.source !== this.value.inputOwner) return reject('not-owner');
                const seconds = (this.value.tick - this.value.chargeStartTick!) * this.config.fixedStepSeconds;
